    "<kbd>Shift</kbd><span class=\"kbd--plus\" aria-hidden=\"true\">+</span><kbd>Ctrl</kbd><span class=\"kbd--plus\" aria-hidden=\"true\">+</span><kbd>Del</kbd>": "<kbd>Maj</kbd><span class=\"kbd--plus\" aria-hidden=\"true\">+</span><kbd>Ctrl</kbd><span class=\"kbd--plus\" aria-hidden=\"true\">+</span><kbd>Suppr</kbd>",
    "<kbd>Shift</kbd><span class=\"kbd--plus\" aria-hidden=\"true\">+</span><kbd>Ctrl</kbd><span class=\"kbd--plus\" aria-hidden=\"true\">+</span><kbd>Page Down</kbd>": "<kbd>Maj</kbd> <span class=\"kbd--plus\" aria-hidden=\"true\">+</span> <kbd>Ctrl</kbd> <span class=\"kbd--plus\" aria-hidden=\"true\">+</span> <kbd>Page suivante</kbd>",
